// Doc-builder printer for the mixed Edge / HTML AST.
//
// Layout rules (see docs/adr/0006):
//   - Block-level children always break onto their own lines, indented one
//     unit relative to the parent.
//   - Inline-only children try to fit on one line; break to multi-line if
//     they overflow printWidth.
//   - HTML attributes fit on one line; if they don't, each goes on its own
//     line at element-indent + 1 with the closing `>` back at element-indent.
//   - Edge expressions and tag args were pre-formatted in the async prepare
//     pass and embedded as `node.formatted` / `node.formattedArgs` strings.

import prettier from 'prettier'
const { group, indent, hardline, softline, line, join, fill, dedent, breakParent } =
  prettier.doc.builders

// Resolve the spacer (string) used inside a mustache. `edgeMustacheSpacing`
// of 1 → a single space; 0 → empty. Applies to {{ }}, {{{ }}}, @{{ }},
// @{{{ }}}, and {{-- … --}}.
function mustacheSpace(options) {
  return options?.edgeMustacheSpacing === 0 ? '' : ' '
}

// Resolve the HTML attribute quote character.
//   "double" (default) → `"`
//   "single"           → `'`
//   "preserve"         → original source quote if known, else `"`
// Falls back to the other quote when the value already contains the
// preferred quote (so we don't produce broken HTML).
function resolveAttrQuote(attr, value, options) {
  const mode = options?.edgeAttributeQuotes ?? 'double'
  let preferred
  if (mode === 'preserve') {
    preferred = attr.valueQuote === "'" ? "'" : '"'
  } else if (mode === 'single') {
    preferred = "'"
  } else {
    preferred = '"'
  }
  const valueString = stringifyAttrValueForQuoteCheck(value)
  if (preferred === '"' && valueString.includes('"')) return "'"
  if (preferred === "'" && valueString.includes("'")) return '"'
  return preferred
}

// Joins everything in the attr value list into a string for the sake of
// quote-collision checking. EdgeExpression placeholders contribute their
// already-formatted inner; we only care about literal quote chars in the
// raw text, not in JS expressions, so embedded expressions contribute
// nothing here.
function stringifyAttrValueForQuoteCheck(value) {
  if (value === null) return ''
  if (typeof value === 'string') return value
  let out = ''
  for (const part of value) {
    if (typeof part === 'string') out += part
  }
  return out
}

// Resolve max blank lines preserved between siblings in block context.
function maxBlankLines(options) {
  const v = options?.edgeBlankLinesInBlocks
  if (typeof v !== 'number' || !Number.isFinite(v) || v < 0) return 1
  return Math.floor(v)
}

// HTML element categorisation.
const VOID = new Set([
  'area',
  'base',
  'br',
  'col',
  'embed',
  'hr',
  'img',
  'input',
  'link',
  'meta',
  'param',
  'source',
  'track',
  'wbr',
])
const RAW_TEXT = new Set(['script', 'style', 'pre', 'textarea'])
const BLOCK = new Set([
  'address',
  'article',
  'aside',
  'blockquote',
  'details',
  'dialog',
  'div',
  'dl',
  'dt',
  'dd',
  'fieldset',
  'figcaption',
  'figure',
  'footer',
  'form',
  'h1',
  'h2',
  'h3',
  'h4',
  'h5',
  'h6',
  'header',
  'hr',
  'html',
  'li',
  'main',
  'nav',
  'ol',
  'p',
  'section',
  'table',
  'thead',
  'tbody',
  'tfoot',
  'tr',
  'td',
  'th',
  'ul',
  'body',
  'head',
  'menu',
  'summary',
  'colgroup',
  'caption',
  'noscript',
  // SVG containers + common leaves. Treated as block so children always
  // sit on their own lines and the SVG isn't inlined into a paragraph
  // group.
  'svg',
  'g',
  'defs',
  'symbol',
  'mask',
  'clippath',
  'pattern',
  'lineargradient',
  'radialgradient',
  'filter',
  'marker',
  'foreignobject',
  'path',
  'circle',
  'ellipse',
  'line',
  'polyline',
  'polygon',
  'rect',
  'text',
  'tspan',
  'image',
  'use',
  'stop',
])

function elementCategory(name) {
  if (VOID.has(name)) return 'void'
  if (RAW_TEXT.has(name)) return 'raw'
  if (BLOCK.has(name)) return 'block'
  return 'inline'
}

// Returns true if a node, when rendered as a sibling, forces the parent
// container to break onto multiple lines.
function isBlockLevel(node) {
  if (!node) return false
  if (node.type === 'EdgeBlock' || node.type === 'EdgeRawBlock') return true
  if (node.type === 'EdgeInline' || node.type === 'EdgeVoid') return true
  if (node.type === 'HTMLElement') {
    const cat = elementCategory(node.name)
    return cat === 'block' || cat === 'void' || cat === 'raw'
  }
  if (node.type === 'HTMLComment' || node.type === 'HTMLDoctype' || node.type === 'HTMLProcInst') {
    return true
  }
  return false
}

// True when a text node is only whitespace.
function isWhitespaceText(node) {
  return node && node.type === 'HTMLText' && /^\s*$/.test(node.value)
}

// Drop pure-whitespace text nodes when at least one sibling is block-level
// (block layout takes over whitespace). Preserve them inside inline runs.
function cleanChildren(children) {
  if (children.length === 0) return []
  const anyBlock = children.some(isBlockLevel)
  if (!anyBlock) {
    // Inline: keep children as-is; inline rendering handles whitespace.
    return children
  }
  return cleanBlockChildren(children)
}

// Block-context cleanup: drop pure-whitespace text nodes, but record how
// many blank lines lived between siblings (the printer caps this at
// edgeBlankLinesInBlocks at render time).
function cleanBlockChildren(children) {
  const out = []
  for (let i = 0; i < children.length; i++) {
    const c = children[i]
    if (isWhitespaceText(c)) {
      const nl = (c.value.match(/\n/g) || []).length
      const blanks = Math.max(0, nl - 1)
      if (out.length > 0 && blanks > 0) {
        const prev = out[out.length - 1]
        out[out.length - 1] = {
          ...prev,
          __blankCount: Math.max(prev.__blankCount ?? 0, blanks),
        }
      }
      continue
    }
    out.push(c)
  }
  return out
}

function collapseInlineWhitespace(children) {
  const out = []
  for (let i = 0; i < children.length; i++) {
    const c = children[i]
    if (c.type === 'HTMLText') {
      // Preserve a single leading/trailing space if the original had any
      // whitespace at the boundary; collapse internal whitespace runs.
      const leading = /^\s/.test(c.value) ? ' ' : ''
      const trailing = /\s$/.test(c.value) ? ' ' : ''
      const middle = c.value.trim().replace(/\s+/g, ' ')
      if (middle === '' && (leading || trailing) && out.length > 0) {
        out.push({ type: 'HTMLText', value: ' ' })
        continue
      }
      if (middle === '') continue
      out.push({ type: 'HTMLText', value: leading + middle + trailing })
    } else {
      out.push(c)
    }
  }
  return out
}

// Render the document. The document root is always a block-level
// container — even when its only child is an inline custom element like
// <tab-container>, trailing whitespace text nodes don't belong in the
// output. Force block-style cleaning so they get dropped.
export function printDocument(nodes, options) {
  const cleaned = cleanBlockChildren(nodes)
  if (cleaned.length === 0) return hardline
  return [printSiblings(cleaned, options), hardline]
}

// Print a list of siblings at the current indent. Returns a Doc.
function printSiblings(siblings, options) {
  const parts = []
  const blankCap = maxBlankLines(options)
  for (let i = 0; i < siblings.length; i++) {
    const node = siblings[i]
    parts.push(printNode(node, options))
    const isLast = i === siblings.length - 1
    if (!isLast) {
      parts.push(hardline)
      // ADR-0007: blank lines are preserved when the next sibling is an
      // HTMLElement *and* the previous sibling is either another
      // HTMLElement (paragraph break between HTML siblings) or an Edge
      // tag (block, inline, or void — blank line after `@end` or after
      // an `@let(...)` / `@!card(...)` line). Edge expressions,
      // comments, and HTML-to-Edge transitions never get a blank line.
      const next = siblings[i + 1]
      const blankCount = Math.min(node.__blankCount ?? 0, blankCap)
      if (
        blankCount > 0 &&
        next?.type === 'HTMLElement' &&
        (node.type === 'HTMLElement' ||
          node.type === 'EdgeBlock' ||
          node.type === 'EdgeInline' ||
          node.type === 'EdgeVoid')
      ) {
        for (let k = 0; k < blankCount; k++) parts.push(hardline)
      }
    }
  }
  return parts
}

function printNode(node, options) {
  switch (node.type) {
    case 'HTMLElement':
      return printElement(node, options)
    case 'HTMLText':
      return printText(node, options)
    case 'HTMLComment':
      return ['<!--', node.value ?? '', '-->']
    case 'HTMLDoctype':
      return `<!${node.value ?? ''}>`
    case 'HTMLProcInst':
      return node.value ?? ''
    case 'EdgeBlock':
      return printEdgeBlock(node, options)
    case 'EdgeRawBlock':
      return printEdgeRawBlock(node, options)
    case 'EdgeInline':
      return printEdgeInline(node, options)
    case 'EdgeVoid':
      return printEdgeVoid(node, options)
    case 'EdgeExpression':
      return printEdgeExpression(node, options)
    case 'EdgeComment':
      return printEdgeComment(node, options)
    default:
      return ''
  }
}

function printText(node, options) {
  // In a block context, cleanChildren drops pure-whitespace nodes; what
  // remains is meaningful text.
  return node.value
}

// ---- HTML element ----

function printElement(node, options) {
  const cat = elementCategory(node.name)
  const open = printOpenTag(node, options, cat)

  if (cat === 'void' || node.isSelfClosing) {
    return open
  }

  if (cat === 'raw' && node.name !== 'pre' && node.name !== 'textarea') {
    // <script> / <style>: pre-formatted content goes between tags,
    // indented one unit and preceded/followed by hardlines.
    const content = node.formattedContent ?? textContent(node)
    if (content.trim() === '') {
      return [open, '</', node.name, '>']
    }
    const lines = content.split('\n')
    return [open, indent([hardline, join(hardline, lines)]), hardline, '</', node.name, '>']
  }

  if (cat === 'raw') {
    // <pre> / <textarea>: keep text verbatim.
    const content = textContent(node)
    return [open, content, '</', node.name, '>']
  }

  const cleanedChildren = cleanChildren(node.children)
  if (cleanedChildren.length === 0) {
    return [open, '</', node.name, '>']
  }

  const anyBlock = cleanedChildren.some(isBlockLevel)
  if (anyBlock) {
    return [
      open,
      indent([hardline, printSiblings(cleanedChildren, options)]),
      hardline,
      '</',
      node.name,
      '>',
    ]
  }

  // Inline content. Whitespace between siblings becomes a `line`
  // separator (space when fits, hardline when group breaks). Text with
  // leading/trailing whitespace gets the same treatment at its edges.
  const innerParts = []
  for (const c of cleanedChildren) {
    if (c.type === 'HTMLText') {
      const v = c.value
      if (/^\s*$/.test(v)) {
        if (innerParts.length > 0) innerParts.push(line)
        continue
      }
      const leading = /^\s/.test(v)
      const trailing = /\s$/.test(v)
      if (leading && innerParts.length > 0) innerParts.push(line)
      innerParts.push(v.trim().replace(/\s+/g, ' '))
      if (trailing) innerParts.push(line)
    } else {
      innerParts.push(printNode(c, options))
    }
  }
  // Drop a trailing line if present (whitespace at end of inline content
  // has no meaning).
  while (innerParts.length > 0 && innerParts[innerParts.length - 1] === line) {
    innerParts.pop()
  }
  if (innerParts.length === 0) {
    return [open, '</', node.name, '>']
  }
  return group([open, indent([softline, innerParts]), softline, '</', node.name, '>'])
}

function printOpenTag(node, options, cat) {
  const isVoid = cat === 'void' || node.isSelfClosing
  if (node.attrs.length === 0) {
    return ['<', node.name, isVoid ? ' />' : '>']
  }

  // Special case: single dynamic attribute with a multi-line expression
  // body. Glue `<tag {{` and `}}>` so the body sits between them, indented.
  if (node.attrs.length === 1 && node.attrs[0].name === '__edge_expr__') {
    const expr = node.attrs[0].value[0]
    const inner = (expr.formatted ?? expr.inner ?? '').trim()
    const { open, close } = exprDelims(expr)
    const sp = mustacheSpace(options)
    if (inner.includes('\n')) {
      const lines = inner.split('\n')
      return [
        '<',
        node.name,
        ' ',
        open,
        indent([hardline, join(hardline, lines)]),
        hardline,
        close,
        isVoid ? ' />' : '>',
      ]
    }
    // Single-line dynamic attr always stays inline with the tag.
    return ['<', node.name, ' ', open, sp, inner, sp, close, isVoid ? ' />' : '>']
  }

  const attrDocs = node.attrs.map((a) => printAttr(a, options))
  const perLine = options?.singleAttributePerLine === true
  // `bracketSameLine` only applies to non-void elements. Void / self-closing
  // tags use `/>` (Prettier-html convention).
  const bracketSameLine = options?.bracketSameLine === true && !isVoid
  const sep = perLine ? hardline : line
  let closer
  if (isVoid) {
    // Self-closing always gets a literal space before `/>` when attrs
    // fit on one line (`<tag a b />`), and `/>` on its own line when
    // attrs break.
    closer = [perLine ? hardline : line, '/>']
  } else if (bracketSameLine) {
    closer = '>'
  } else {
    closer = [perLine ? hardline : softline, '>']
  }
  return group(['<', node.name, indent([sep, join(sep, attrDocs)]), closer])
}

function exprDelims(expr) {
  switch (expr.kind) {
    case 'raw':
      return { open: '{{{', close: '}}}' }
    case 'literal':
      return { open: '@{{', close: '}}' }
    case 'literal-raw':
      return { open: '@{{{', close: '}}}' }
    default:
      return { open: '{{', close: '}}' }
  }
}

function printAttr(attr, options) {
  if (attr.name === '__edge_expr__') {
    const expr = attr.value[0]
    return printEdgeExpression(expr, options)
  }
  // Alpine.js / Livewire attributes were masked by preprocess so
  // edge-lexer wouldn't mistake them for Edge tags. Restore the `@`
  // prefix on the way out.
  const name = attr.name.startsWith('__edge_alpine__')
    ? '@' + attr.name.slice('__edge_alpine__'.length)
    : attr.name
  if (attr.value === null) return name
  const quote = resolveAttrQuote(attr, attr.value, options)
  return [name, '=', quote, printAttrValueDoc(attr.value, options), quote]
}

function printAttrValueDoc(value, options) {
  const items = Array.isArray(value) ? value : [value]
  const parts = []
  for (const item of items) {
    if (typeof item === 'string') {
      if (item.includes('\n')) {
        const lines = item.split('\n')
        for (let i = 0; i < lines.length; i++) {
          if (i === 0) {
            parts.push(lines[i])
          } else {
            parts.push(hardline)
            parts.push(lines[i].replace(/^\s+/, ''))
          }
        }
      } else {
        parts.push(item)
      }
    } else {
      parts.push(printEdgeExpression(item, options))
    }
  }
  // If multi-line, wrap continuation in indent so hardlines land at
  // attr-indent + 1 unit deeper.
  const firstHL = parts.findIndex((p) => p === hardline)
  if (firstHL >= 0) {
    return [...parts.slice(0, firstHL), indent(parts.slice(firstHL))]
  }
  return parts
}

function textContent(elem) {
  let out = ''
  for (const c of elem.children) {
    if (c.type === 'HTMLText') out += c.value
  }
  return out
}

// ---- Edge nodes ----

function printEdgeExpression(node, options) {
  const open =
    node.kind === 'raw'
      ? '{{{'
      : node.kind === 'literal'
        ? '@{{'
        : node.kind === 'literal-raw'
          ? '@{{{'
          : '{{'
  const close = node.kind === 'raw' ? '}}}' : node.kind === 'literal-raw' ? '}}}' : '}}'
  const inner = (node.formatted ?? node.inner ?? '').trim()
  if (inner.includes('\n')) {
    const lines = inner.split('\n')
    return [open, indent([hardline, join(hardline, lines)]), hardline, close]
  }
  const sp = mustacheSpace(options)
  return [open, sp, inner, sp, close]
}

function printEdgeComment(node, options) {
  const inner = (node.inner ?? '').replace(/\r\n/g, '\n')
  const sp = mustacheSpace(options)
  if (!inner.includes('\n')) {
    const body = inner.trim()
    return ['{{--', body ? `${sp}${body}${sp}` : sp, '--}}']
  }
  // Multi-line: trim each line, indent under {{--.
  const lines = inner.split('\n').map((l) => l.trim())
  // Drop fully blank leading and trailing lines.
  while (lines.length > 0 && lines[0] === '') lines.shift()
  while (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return ['{{--', indent([hardline, join(hardline, lines)]), hardline, '--}}']
}

function printEdgeInline(node, options) {
  return printTagCall(node.name, false, node.formattedArgs ?? node.args ?? '')
}

function printEdgeVoid(node, options) {
  return printTagCall(node.name, true, node.formattedArgs ?? node.args ?? '')
}

function printTagCall(name, isVoid, formattedArgs) {
  const prefix = isVoid ? '@!' : '@'
  const args = formattedArgs ?? ''
  if (!args.includes('\n')) {
    return [prefix, name, '(', args, ')']
  }
  // Multi-line args: glue first line to `(` and last line to `)` so an
  // object/array literal collapses against the call parens, matching
  // prettier-babel's own call-with-trailing-object layout.
  const lines = formattedArgs.split('\n')
  return [prefix, name, '(', lines[0], ...lines.slice(1).flatMap((l) => [hardline, l]), ')']
}

function printEdgeRawBlock(node, options) {
  const open = `@raw${node.openSwallow ? '~' : ''}`
  const close = `@end${node.closeSwallow ? '~' : ''}`
  const body = (node.body ?? '').replace(/^\n+|\n+$/g, '')
  if (body === '') return [open, hardline, close]
  const lines = body.split('\n')
  // Body is verbatim — no `indent()`. Each line emits with the leading
  // whitespace the user wrote, relative to the @raw opener.
  return [open, hardline, join(hardline, lines), hardline, close]
}

function printEdgeBlock(node, options) {
  const parts = []
  for (let i = 0; i < node.branches.length; i++) {
    const branch = node.branches[i]
    parts.push(printBranchOpener(branch))
    const body = normalizeBlockBody(branch.body ?? [])
    if (body.length > 0) {
      parts.push(indent([hardline, printSiblings(body, options)]))
    }
    parts.push(hardline)
  }
  parts.push('@end')
  return parts
}

// Normalises an Edge block's body. The body is treated as block context:
// pure-whitespace text nodes are dropped, multi-line text nodes are split
// into per-line nodes with leading/trailing whitespace trimmed. Blank
// lines between content lines are preserved as a `__blankCount` count on
// the preceding sibling (printer caps via edgeBlankLinesInBlocks).
function normalizeBlockBody(children) {
  // Drop pure-whitespace siblings (block context — printer controls
  // spacing). Accumulate blank-line counts onto the preceding sibling.
  const dropped = []
  let blankPending = 0
  for (const c of children) {
    if (isWhitespaceText(c)) {
      const nl = (c.value.match(/\n/g) || []).length
      blankPending = Math.max(blankPending, Math.max(0, nl - 1))
      continue
    }
    if (blankPending > 0 && dropped.length > 0) {
      const prev = dropped[dropped.length - 1]
      dropped[dropped.length - 1] = {
        ...prev,
        __blankCount: Math.max(prev.__blankCount ?? 0, blankPending),
      }
    }
    blankPending = 0
    dropped.push(c)
  }

  // Now split multi-line text nodes into per-line nodes.
  const out = []
  const bumpBlankOnPrev = (n) => {
    if (n <= 0 || out.length === 0) return
    const prev = out[out.length - 1]
    out[out.length - 1] = {
      ...prev,
      __blankCount: Math.max(prev.__blankCount ?? 0, n),
    }
  }
  for (const c of dropped) {
    if (c.type === 'HTMLText' && c.value.includes('\n')) {
      const lines = c.value.split('\n').map((l) => l.replace(/\s+$/, '').replace(/^\s+/, ''))
      while (lines.length > 0 && lines[0] === '') lines.shift()
      while (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
      if (lines.length === 0) continue
      let blankRun = 0
      for (const line of lines) {
        if (line === '') {
          blankRun += 1
          continue
        }
        if (blankRun > 0) {
          bumpBlankOnPrev(blankRun)
          blankRun = 0
        }
        out.push({ type: 'HTMLText', value: line })
      }
      // Carry the source's __blankCount onto the last emitted line.
      if (c.__blankCount && out.length > 0) bumpBlankOnPrev(c.__blankCount)
    } else if (c.type === 'HTMLText') {
      // Single-line text: trim and emit.
      const trimmed = c.value.trim()
      if (trimmed === '') continue
      const node = { type: 'HTMLText', value: trimmed }
      if (c.__blankCount) node.__blankCount = c.__blankCount
      out.push(node)
    } else {
      out.push(c)
    }
  }
  return out
}

function printBranchOpener(branch) {
  const args = branch.formattedArgs ?? ''
  // @else is the only branch keyword that takes no parens. Every other
  // opener (and @elseif) is seekable.
  if (branch.name === 'else' && args === '') return `@${branch.name}`
  if (!args.includes('\n')) return `@${branch.name}(${args})`
  const lines = args.split('\n')
  return [`@${branch.name}(`, lines[0], ...lines.slice(1).flatMap((l) => [hardline, l]), ')']
}
